import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String userId = (String) req.getSession().getAttribute("user_id");

        if (userId == null) {
            resp.sendError(401, "Not authenticated");
            return;
        }

        // Validate report type against whitelist
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Sort column - we do server-side validation but allow dynamic ORDER BY
        // since prepared statements don't support parameterized ORDER BY clauses
        if (sortCol == null) sortCol = "created_at";

        // Strip obvious injection attempts
        sortCol = sortCol.replaceAll("[;'\"]", "");
        sortCol = sortCol.replaceAll("--", "");
        sortCol = sortCol.replaceAll("/\\*", "");

        String[] dates = dateRange != null ? dateRange.split("_") : new String[]{"2020-01-01", "2099-12-31"};

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Use prepared statement for the WHERE clause parameters
            String query = "SELECT id, title, amount, created_at, status FROM reports "
                         + "WHERE user_id = ? AND report_type = ? "
                         + "AND created_at BETWEEN ? AND ? "
                         + "ORDER BY " + sortCol + " ASC "
                         + "LIMIT 500";

            log.info("Executing report query for user=" + userId + " type=" + reportType);

            PreparedStatement stmt = conn.prepareStatement(query);
            stmt.setString(1, userId);
            stmt.setString(2, reportType);
            stmt.setString(3, dates[0]);
            stmt.setString(4, dates[1]);

            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{\"results\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.print("{\"id\":" + rs.getInt("id"));
                out.print(",\"title\":\"" + StringEscapeUtils.escapeJson(rs.getString("title")) + "\"");
                out.print(",\"amount\":" + rs.getDouble("amount"));
                out.print(",\"created_at\":\"" + rs.getString("created_at") + "\"");
                out.print(",\"status\":\"" + StringEscapeUtils.escapeJson(rs.getString("status")) + "\"");
                out.print("}");
                first = false;
            }
            out.print("]}");
            out.flush();
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private boolean isValidReportType(String type) {
        if (type == null) return false;
        return type.equals("expense") || type.equals("revenue") 
            || type.equals("audit") || type.equals("summary");
    }
}
